import{_ as e,o as r,c as d,a0 as a}from"./chunks/framework.BQGW-Zpy.js";const f=JSON.parse('{"title":"Functional Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/functional-requirements.md","filePath":"architecture/functional-requirements.md"}'),n={name:"architecture/functional-requirements.md"};function o(i,t,s,c,u,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th><th>Priority</th></tr></thead><tbody><tr><td>FR-01</td><td>Quote a corridor: fee, FX rate, arrival estimate</td><td>Must</td></tr><tr><td>FR-02</td><td>Accept fiat through a licensed PSP sandbox; never touch the funds</td><td>Must</td></tr><tr><td>FR-03</td><td>Receive and verify the PSP webhook</td><td>Must</td></tr><tr><td>FR-04</td><td>Execute a real stablecoin transfer on Hedera testnet</td><td>Must</td></tr><tr><td>FR-05</td><td>Canonicalise and hash the compliance record</td><td>Must</td></tr><tr><td>FR-06</td><td>Anchor the hash on HCS; store topic, sequence, consensus timestamp</td><td>Must</td></tr><tr><td>FR-07</td><td>Instruct payout through a licensed payout sandbox</td><td>Must</td></tr><tr><td>FR-08</td><td>Verify an anchor via Mirror Node without our API</td><td>Must</td></tr><tr><td>FR-09</td><td>Detect tampering: recompute and compare</td><td>Must</td></tr><tr><td>FR-10</td><td>Complete the entire flow with no wallet artefact visible</td><td>Must</td></tr><tr><td>FR-11</td><td>Never persist client funds, keys or balances</td><td>Must</td></tr><tr><td>FR-12</td><td>Retry a failed anchor without losing the record</td><td>Should</td></tr><tr><td>FR-13</td><td>Show the corridor&#39;s liquidity source explicitly in the UI</td><td>Should</td></tr></tbody></table><h3 id="_18-1-non-functional" tabindex="-1">18.1 Non-functional <a class="header-anchor" href="#_18-1-non-functional" aria-label="Permalink to &quot;18.1 Non-functional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Requirement</th></tr></thead><tbody><tr><td>Legal</td><td>No custody. No client funds. No client crypto-assets. Ever.</td></tr><tr><td>Privacy</td><td>No personal data on-chain; hash + pseudonymous reference only</td></tr><tr><td>Security</td><td>Operator key in <code>.env</code>, never committed; PSP webhook signature verified</td></tr><tr><td>Integrity</td><td>Every anchor retains local hash, topic, sequence, consensus timestamp</td></tr><tr><td>Verifiability</td><td>A third party verifies via Mirror Node with no access to us</td></tr><tr><td>Attribution</td><td>The UI names the licensed parties in the flow, we do not present their service as ours</td></tr></tbody></table><hr>',5)])])}const m=e(n,[["render",o]]);export{f as __pageData,m as default};
